namespace qqworld_collector\module\collecting; use qqworld_collector\lib; class ajax extends lib { var $log_id = 'collection-project'; public function init() { add_action( 'wp_ajax_qqworld-collector-get-source-links', array($this, 'get_source_links') ); add_action( 'wp_ajax_nopriv_qqworld-collector-get-source-links', array($this, 'get_source_links') ); add_action( 'wp_ajax_qqworld-collector-grab-source-link', array($this, 'grab_source_link') ); add_action( 'wp_ajax_nopriv_qqworld-collector-grab-source-link', array($this, 'grab_source_link') ); add_action( 'wp_ajax_qqworld-collector-grab-source-contents', array($this, 'grab_source_contents') ); add_action( 'wp_ajax_nopriv_qqworld-collector-grab-source-contents', array($this, 'grab_source_contents') ); add_action( 'wp_ajax_qqworld-collector-grab-source-comments', array($this, 'grab_source_comments') ); add_action( 'wp_ajax_nopriv_qqworld-collector-grab-source-comments', array($this, 'grab_source_comments') ); add_action( 'wp_ajax_qqworld-collector-grab-content-from-url', array($this, 'grab_content_from_url') ); add_action( 'wp_ajax_nopriv_qqworld-collector-grab-content-from-url', array($this, 'grab_content_from_url') ); add_action( 'wp_ajax_qqworld-collector-update-last-collected-time', array($this, 'update_last_collected_time') ); add_action( 'wp_ajax_nopriv_qqworld-collector-update-last-collected-time', array($this, 'update_last_collected_time') ); add_action( 'wp_ajax_qqworld-collector-collection-collect-again', array($this, 'ajax_collect_again') ); add_action( 'wp_ajax_nopriv_qqworld-collector-collection-collect-again', array($this, 'ajax_collect_again') ); add_action( 'wp_ajax_qqworld-collector-collection-remote-publish', array($this, 'ajax_remote_publish') ); add_action( 'wp_ajax_nopriv_qqworld-collector-collection-remote-publish', array($this, 'ajax_remote_publish') ); add_action( 'wp_ajax_qqworld-collector-add-excluded-url', array($this, 'add_excluded_url') ); add_action( 'wp_ajax_nopriv_qqworld-collector-add-excluded-url', array($this, 'add_excluded_url') ); add_action( 'wp_ajax_qqworld-collector-import-collection-project', array($this, 'import_collection_project') ); add_action( 'wp_ajax_nopriv_qqworld-collector-import-collection-project', array($this, 'import_collection_project') ); add_action( 'wp_ajax_qqworld-collector-schedule-collecting', array($this, 'set_schedule_collecting') ); add_action( 'wp_ajax_nopriv_qqworld-collector-schedule-collecting', array($this, 'set_schedule_collecting') ); add_action( 'wp_ajax_qqworld-collector-cancel-schedule-collecting', array($this, 'cancel_schedule_collecting') ); add_action( 'wp_ajax_nopriv_qqworld-collector-cancel-schedule-collecting', array($this, 'cancel_schedule_collecting') ); add_action( 'wp_ajax_qqworld-collector-set-schedule-collecting-settings', array($this, 'set_schedule_collecting_settings') ); add_action( 'wp_ajax_nopriv_qqworld-collector-set-schedule-collecting-settings', array($this, 'set_schedule_collecting_settings') ); add_action( 'wp_ajax_qqworld-collector-wipe-all-collecting-tasks', array($this, 'wipe_all_tasks') ); add_action( 'wp_ajax_nopriv_qqworld-collector-wipe-all-collecting-tasks', array($this, 'wipe_all_tasks') ); add_action( 'wp_ajax_qqworld-collector-remote-publish-get-categories-list', array($this, 'get_categories_list') ); add_action( 'wp_ajax_nopriv_qqworld-collector-remote-publish-get-categories-list', array($this, 'get_categories_list') ); add_action( 'wp_ajax_qqworld-collector-remote-publish-get-terms-list', array($this, 'get_terms_list') ); add_action( 'wp_ajax_nopriv_qqworld-collector-remote-publish-get-terms-list', array($this, 'get_terms_list') ); add_action( 'wp_ajax_qqworld-collector-remote-publish-restart-publishing', array($this, 'restart_publishing') ); add_action( 'wp_ajax_nopriv_qqworld-collector-remote-publish-restart-publishing', array($this, 'restart_publishing') ); add_action( 'wp_ajax_qqworld-collector-remote-publish-do-publishing', array($this, 'do_publishing') ); add_action( 'wp_ajax_nopriv_qqworld-collector-remote-publish-do-publishing', array($this, 'do_publishing') ); add_action( 'wp_ajax_qqworld-collector-auto-login', array($this, 'ajax_auto_login') ); add_action( 'wp_ajax_nopriv_qqworld-collector-auto-login', array($this, 'ajax_auto_login') ); add_action( 'wp_ajax_qqworld-collector-get-form-arguments', array($this, 'get_form_arguments') ); add_action( 'wp_ajax_nopriv_qqworld-collector-get-form-arguments', array($this, 'get_form_arguments') ); } public function get_source_links() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; if ( isset($_POST['collection_project_id']) ) { $pid = $_POST['collection_project_id']; $args = get_post_meta( $pid, $this->setting_name, true ); } elseif ( isset($_POST[$this->setting_name]) ) { $args = $this->deep_stripslashes($_POST[$this->setting_name]); $pid = $_POST['post_ID']; } $links = isset($args['links']) ? $args['links'] : ''; $archive = isset($args['archive']) ? $args['archive'] : ''; $settings = isset($args['settings']) ? $args['settings'] : ''; if (!empty($_POST['sourceLinks']) || !empty($_POST['bulk-links']['structure'])) { $count = 0; foreach ($links as $guid => &$link) { if (!preg_match('/^i\-/i', $guid)) continue; if ($count > 0) unset($links[$guid]); else { $count++; $link['static-links'] = !empty($_POST['sourceLinks']) ? $_POST['sourceLinks'] : ''; if (!empty($_POST['bulk-links']['structure'])) $link['bulk-links'] = $_POST['bulk-links']; else $link['bulk-links']['structure'] == ''; } } } if ($links) { $source_links_group = $this->core->engine->get_source_links($links, $settings); if (isset($_POST['args'])) { if (!empty($source_links_group)) foreach ($source_links_group as &$group) { $group['args'] = array_merge($group['args'], $_POST['args']); } } $results = array( 'success' => 1, 'source_links_group' => $source_links_group, 'archive' => $archive, 'settings' => $settings, 'pid' => $pid ); } else { $results = array( 'success' => 0, 'links' => $links, 'archive' => $archive, 'settings' => $settings ); } echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function grab_source_link() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; if (!isset($_POST['source_link']) || !isset($_POST['archive']) || !isset($_POST['settings'])) exit; extract($_POST); $archive = $this->deep_stripslashes($archive); $results = $this->core->engine->grab_source_link($source_link, $archive, $settings, $mode); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function grab_source_contents() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; if ( isset($_POST['collection_project_id']) ) { $pid = $_POST['collection_project_id']; $args = get_post_meta( $pid, $this->setting_name, true ); } elseif ( isset($_POST[$this->setting_name]) ) { $pid = $_POST['post_ID']; $args = $this->deep_stripslashes($_POST[$this->setting_name]); } $links = isset($args['links']) ? $args['links'] : array(); $singular = isset($args['singular']) ? $args['singular'] : array(); $comments = isset($args['comments']) ? $args['comments'] : array(); $settings = isset($args['settings']) ? $args['settings'] : array(); extract($_POST); $singular = $this->deep_stripslashes($singular); $mode = isset($debug) && $debug ? 'test' : 'collecting'; if (isset($source_link)) { $links = isset($args['links']) ? $args['links'] : array(); $link_group = current($links); $results = $this->core->engine->grab_source_content($source_link, $singular, $settings, $mode); if (isset($save) && $save) $results = $this->core->engine->grab_source_comments($results, $source_link, $comments, $settings, $mode); } elseif (isset($source_results)) { $source_results = json_decode(stripslashes($source_results), true); $results = $source_results['results']; $link_group = $source_results['args']; $results = $this->core->engine->grab_source_content($results, $singular, $settings, $mode); if (isset($save) && $save) $results = $this->core->engine->grab_source_comments($results, $results['collected_items'], $comments, $settings, $mode); } $json = json_encode($results, JSON_INVALID_UTF8_IGNORE); if (!$json) { do_action( 'qqworld-collector-log', $this->log_id, 'json_encode fail:', json_last_error_msg() ); $results['collected_items']['post_content'] = mb_convert_encoding($results['collected_items']['post_content'], 'UTF-8', array('GB2312', 'GBK', 'BIG5', 'ASCII', 'UTF-8')); } $show_json = $results; if (isset($save) && $save) { $debug = isset($debug) ? $debug : false; $results['mode'] = 'manual'; if ( !has_filter('qqworld-collector-save-collected-posts') ) { do_action( 'qqworld-collector-log', $this->log_id, 'Can not save collected posts (ajax grab source contents):', print_r($results, true) ); $show_json['success'] = 0; } else { if (isset($source_results['interval_times'])) $results['interval_times'] = $source_results['interval_times']; $results = apply_filters( 'qqworld-collector-save-collected-posts', $results, $pid, $link_group, $debug ); if (isset($results['interval_times'])) $show_json['interval_times'] = $results['interval_times']; if (isset($results['duplicated'])) $show_json['duplicated'] = $results['duplicated']; if (isset($results['error'])) $show_json['error'] = $results['error']; if (isset($results['ignored'])) $show_json['ignored'] = $results['ignored']; if (isset($results['msg'])) $show_json['msg'] = $results['msg']; $show_json['success'] = $results['success']; } } if ($show_json) print json_encode($show_json, JSON_INVALID_UTF8_IGNORE); exit; } public function grab_source_comments() { $pid = $_POST['post_ID']; $args = $this->deep_stripslashes($_POST[$this->setting_name]); $links = isset($args['links']) ? $args['links'] : array(); $comments = isset($args['comments']) ? $args['comments'] : array(); $settings = isset($args['settings']) ? $args['settings'] : array(); extract($_POST); $comments = $this->deep_stripslashes($comments); $mode = 'test'; $links = isset($args['links']) ? $args['links'] : array(); $link_group = current($links); $results = array( 'success' => 1, 'collected_items' => array() ); $results = $this->core->engine->grab_source_comments($results, $source_link, $comments, $settings, $mode); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function grab_content_from_url() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; if (!isset($_POST[$this->setting_name]) ) exit; $args = $this->deep_stripslashes($_POST[$this->setting_name]); $settings = isset($args['settings']) ? $args['settings'] : array(); $proxy = isset($settings['proxy']) ? filter_var($settings['proxy'], FILTER_VALIDATE_BOOLEAN) : false; $charset = isset($settings['charset']) && !empty($settings['charset']) ? $settings['charset'] : 'auto'; $auto_login = isset($settings['auto-login']) && !empty($settings['auto-login']) ? $settings['auto-login'] : ''; $test = isset($args['test']) ? $args['test'] : array(); $url = isset($test['url']) ? $test['url'] : ''; $method = isset($test['method']) ? $test['method'] : 'GET'; $headers = isset($test['headers']) ? $test['headers'] : ''; $download_args = array(); if ($headers) $download_args['headers'] = apply_filters( 'qqworld-collector-parse-headers-by-auto-login', $headers, $auto_login ); if ($proxy) $download_args['proxy'] = $proxy; $download_args['charset'] = $charset; extract($_POST); if ($method == 'POST') { $download_args['method'] = $method; $urls = preg_split('/\n/i', $url); if (count($urls) > 1) { $url = $urls[0]; $download_args['content'] = stripslashes($urls[1]); } } if ($method == 'HEAD') { $download_args['recursive'] = false; print apply_filters( 'qqworld-collector-get-headers-from-url', $url, $download_args ); } else { $result = apply_filters( 'qqworld-collector-download-from-url', $url, $download_args ); if ($result['file'] && $_POST['enabled_collecting_method'] == 1) { $items = $this->core->engine->parse_html($result['file'], $_POST['collecting-method']); if (is_array($items)) $items = implode(', ', $items); $content = $items; } else { $content = $result['file']; } print $content; } exit; } public function update_last_collected_time() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; if (!isset($_POST['id'])) exit; $id = $_POST['id']; $last_time = current_time('timestamp'); update_post_meta($id, 'last-collected-time', $last_time); $results = array( 'id' => $id, 'msg' => date(get_option('date_format') . ' ' . get_option('time_format'), $last_time) ); echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function ajax_collect_again() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; if (!isset($_POST['id'])) exit; $post_id = $_POST['id']; $pid = $_POST['pid']; $results = $this->collect_again($post_id, $pid); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function parse_post_before_remote_publish($post, $post_id = null) { $post_id = $post_id ? $post_id : $post['ID']; unset($post['ID']); unset($post['comment_status']); unset($post['ping_status']); unset($post['post_password']); unset($post['to_ping']); unset($post['pinged']); unset($post['post_content_filtered']); unset($post['post_parent']); unset($post['menu_order']); unset($post['comment_count']); unset($post['guid']); unset($post['filter']); unset($post['vote_up']); unset($post['vote_down']); unset($post['ancestors']); unset($post['page_template']); unset($post['post_modified']); unset($post['post_modified_gmt']); unset($post['post_mime_type']); $post['post_name'] = urldecode($post['post_name']); $user = get_user_by('id', $post['post_author']); $post['post_author'] = $user->data->display_name; $post_meta = get_post_meta($post_id); if (!empty($post_meta)) { $post['meta_input'] = array(); foreach ($post_meta as $meta_key => $meta_values) { $meta_value = $meta_values[0]; $post['meta_input'][$meta_key] = $meta_value; } } unset($post['post_category']); unset($post['tags_input']); if (isset($post['tax_input'])) unset($post['tax_input']); $taxonomies = get_object_taxonomies( $post['post_type'] ); if (!empty($taxonomies)) { $post['tax_input'] = array(); foreach ($taxonomies as $taxonomy) { $terms = get_the_terms($post_id, $taxonomy); if (!empty($terms)) { $post['tax_input'][$taxonomy] = array(); foreach ($terms as $term) { $post['tax_input'][$taxonomy][] = $taxonomy == 'post_format' ? $term->slug : $term->name; } } } } return $post; } public function ajax_remote_publish() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; if (!isset($_POST['id'])) exit; $post_id = $_POST['id']; $pid = $_POST['pid']; if (is_numeric($pid)) { $args = get_post_meta($pid, 'qqworld-collection-project', true); if ($args) { $settings = isset($args['settings']) ? $args['settings'] : array(); $remote_publish = isset($settings['remote-publish']) ? $settings['remote-publish'] : array(); $remote_publish_remote_website = isset($remote_publish['remote-website']) ? $remote_publish['remote-website'] : 0; } else { $remote_publish_remote_website = ''; } } else { $remote_publish_remote_website = $pid; } $post = get_post($post_id, ARRAY_A); $post = $this->parse_post_before_remote_publish($post, $post_id); $config = array( 'post' => $post, 'remote_publish_remote_website' => $remote_publish_remote_website, 'post_id' => $post_id, 'args' => $args, 'pid' => $pid ); $status = apply_filters( 'qqworld-collector-remote-publish', $config ); $results = array( 'success' => $status ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function collect_again($post_id, $pid = null) { $pid = $pid ? $pid : get_post_meta( $post_id, '_collection_project', true ); $url = get_post_meta( $post_id, 'source-link', true ); if (!$pid || !$url) exit; $args = get_post_meta( $pid, $this->setting_name, true ); $singular = isset($args['singular']) ? $args['singular'] : array(); $comments = isset($args['comments']) ? $args['comments'] : array(); $settings = isset($args['settings']) ? $args['settings'] : array(); $results = $this->core->engine->grab_source_content($url, $singular, $settings); $results = $this->core->engine->grab_source_comments($results, $url, $comments, $settings); $link_group = current($args['links']); $results['ID'] = $post_id; $debug = false; $results['mode'] = 'manual'; if ( !has_filter('qqworld-collector-save-collected-posts') ) { do_action( 'qqworld-collector-log', $this->log_id, 'Can not save collected posts (ajax collect again):', print_r($results, true) ); $results['success'] = 0; } else { $results = apply_filters( 'qqworld-collector-save-collected-posts', $results, $pid, $link_group, $debug ); } return $results; } public function add_excluded_url() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; if ( !isset($_POST['pid']) || !isset($_POST['url']) ) { $result = array( 'success' => 0 ); } else { extract($_POST); $args = get_post_meta( $pid, $this->setting_name, true ); if (!$args) $args = array('settings' => array()); if ( isset($args['settings']['excluded-url']) && !empty($args['settings']['excluded-url']) ) { $args['settings']['excluded-url'] .= "\n" . $url; } else { $args['settings']['excluded-url'] = $url; } update_post_meta( $pid, $this->setting_name, $args ); $result = array( 'success' => 1 ); } print json_encode($result, JSON_INVALID_UTF8_IGNORE); exit; } public function slash($str) { $str = str_replace('\\', '\\\\', $str); return $str; } public function import_collection_project() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; extract($_POST); $result = 0; if (isset($codes)) { $codes = trim($codes); $codes = json_decode(base64_decode($codes), true); $codes['meta_input']['qqworld-collection-project'] = map_deep($codes['meta_input']['qqworld-collection-project'], array($this, 'slash')); if ($codes) { if (isset($id) && $id) { $codes['ID'] = $id; $result = wp_update_post($codes); } else { $result = wp_insert_post($codes); } } } print $result; exit; } public function set_schedule_collecting() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; if (!isset($_POST['pid']) || !isset($_POST['recurrence']) || !isset($_POST['after'])) exit; $pid = intval($_POST['pid']); $recurrence = $_POST['recurrence']; $after = intval( $_POST['after']); $offset = $after * 60; $timestamp = wp_next_scheduled( 'qqworld-collector-schedule-collecting', array($pid) ); if ( !$timestamp ) { if ($recurrence) { $timestamp = wp_schedule_event( time()+$offset, $recurrence, 'qqworld-collector-schedule-collecting', array($pid) ); } else { $timestamp = wp_schedule_single_event( time()+$offset, 'qqworld-collector-schedule-collecting', array($pid) ); } if ($timestamp !== false) { $results = array( 'success' => 1, 'msg' => __('Successfully scheduled.', $this->text_domain) ); } else { $results = array( 'success' => 0, 'msg' => __('Scheduled failed.', $this->text_domain) ); } } else { if ($recurrence) { $timestamp = wp_reschedule_event( time()+$offset, $recurrence, 'qqworld-collector-schedule-collecting', array($pid) ); } else { wp_clear_scheduled_hook( 'qqworld-collector-schedule-collecting', array($pid) ); $timestamp = wp_schedule_single_event( time()+$offset, 'qqworld-collector-schedule-collecting', array($pid) ); } if ($timestamp !== false) { $results = array( 'success' => 1, 'msg' => __('The task is exists, already rescheduled.', $this->text_domain) ); } else { $results = array( 'success' => 0, 'msg' => __('The task is exists, rescheduled failed.', $this->text_domain) ); } } if ($recurrence) { update_post_meta($pid, 'recurrence', $recurrence); } $results['pid'] = $pid; $results['post'] = $_POST; echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function cancel_schedule_collecting() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; if ( !isset($_POST['pid']) ) exit; $pid = intval($_POST['pid']); $timestamp = wp_next_scheduled( 'qqworld-collector-schedule-collecting', array($pid) ); if ( $timestamp ) { wp_clear_scheduled_hook( 'qqworld-collector-schedule-collecting', array($pid) ); $results = array( 'success' => 1, 'msg' => __('Successfully canceled.', $this->text_domain) ); } else { $results = array( 'success' => 0, 'msg' => __('The task is not exists.', $this->text_domain) ); } update_post_meta($pid, 'recurrence', ''); $results['pid'] = $pid; echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function set_schedule_collecting_settings() { extract($_REQUEST); if ( ! wp_verify_nonce( $nonce, $action ) ) wp_die( 'Nope! Security check failed!' ); $this->clear_all_crons('qqworld-collector-schedule-collecting'); $this->clear_all_crons('qqworld-collector-schedule-all-collecting'); $count = 0; $after *= 60; $queue = filter_var($queue, FILTER_VALIDATE_BOOLEAN); if ($queue) { if ($task) { $timestamp = wp_schedule_event( time()+$after, $task, 'qqworld-collector-schedule-all-collecting' ); } else { $timestamp = wp_schedule_single_event( time()+$after, 'qqworld-collector-schedule-all-collecting' ); } } else { for ($paged=0; $paged<1000; $paged++) { $args = array( 'post_type' => 'qqworld-collections', 'posts_per_page' => 1000, 'offset' => 1000*$paged ); $projects = get_posts($args); if (!empty($projects)) { foreach ($projects as $project) { $pid = $project->ID; $offset = $after + $interval * 60 * $count; if ($task) { $timestamp = wp_schedule_event( time()+$offset, $task, 'qqworld-collector-schedule-collecting', array($pid) ); update_post_meta($pid, 'recurrence', $task); } else { $timestamp = wp_schedule_single_event( time()+$offset, 'qqworld-collector-schedule-collecting', array($pid) ); } $count++; } } else { break; } } } $redirect_uri = admin_url('edit.php?post_type=qqworld-collections'); wp_redirect( $redirect_uri ); exit; } public function wipe_all_tasks() { global $wpdb; if (!current_user_can($this->options->qc_authorization_who_can_use)) exit; $this->clear_all_crons('qqworld-collector-schedule-collecting'); $this->clear_all_crons('qqworld-collector-schedule-all-collecting'); $wpdb->update( $wpdb->postmeta, array('meta_value' => ''), array('meta_key' => 'recurrence'), array('%s'), array('%s') ); $results = array( 'success' => 1, 'msg' => __('All schedule tasks has been canceled successfully.', $this->text_domain) ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function get_categories_list() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; if (isset($_REQUEST['posttype']) && !empty($_REQUEST['posttype'])) { if (!class_exists('Walker_Remote_Publish_Singular_Checklist')) require QQWORLD_COLLECTOR_DIR . 'lib' . DIRECTORY_SEPARATOR . 'collector' . DIRECTORY_SEPARATOR . 'classes' . DIRECTORY_SEPARATOR . 'class.Walker_Remote_Publish_Singular_Checklist.php'; $posttype = $_REQUEST['posttype']; $taxonomies = get_object_taxonomies($posttype); if (!empty($taxonomies)) foreach ($taxonomies as $tax) { $taxonomy = get_taxonomy($tax); if ($tax != 'post_format' && !$taxonomy->hierarchical) continue; echo '<div id="'.$tax.'div" post-type="'.$tax.'" class="postbox"><div class="hndle">'.$taxonomy->labels->name.'</div><div class="inside"><div id="'.$tax.'-all" class="tabs-panel"><ul>'; wp_terms_checklist('', array( 'taxonomy' => $tax, 'walker' => new Walker_Remote_Publish_Singular_Checklist )); echo '</ul></div></div></div>'; } else _e('No taxonomies found.', $this->text_domain); } exit; } public function get_terms_list() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; if (!class_exists('Walker_Remote_Publish_Archive_Checklist')) require QQWORLD_COLLECTOR_DIR . 'lib' . DIRECTORY_SEPARATOR . 'collector' . DIRECTORY_SEPARATOR . 'classes' . DIRECTORY_SEPARATOR . 'class.Walker_Remote_Publish_Archive_Checklist.php'; $tax = $_POST['taxonomy']; $taxonomy = get_taxonomy($tax); echo '<div id="'.$tax.'div" post-type="'.$tax.'" class="postbox"><div class="hndle">'.$taxonomy->labels->name.'</div